CREATE TABLE shop.main.sales (sale_id INTEGER NOT NULL, region VARCHAR NOT NULL, channel VARCHAR, team_id INTEGER NOT NULL, quantity INTEGER NOT NULL, amount DECIMAL(10, 2) NOT NULL, cost DECIMAL(10, 2) NOT NULL, voided BOOLEAN NOT NULL, sale_date DATE NOT NULL, sold_at TIMESTAMPTZ NOT NULL);
CREATE TABLE shop.main.targets (region VARCHAR NOT NULL, target INTEGER NOT NULL);
CREATE TABLE shop.main.returns (return_id INTEGER NOT NULL, sale_id INTEGER NOT NULL, refund DECIMAL(10, 2) NOT NULL);
